const updateWatch = `-- name: UpdateWatch :execrows
UPDATE watches SET
    channel_id = $1, target_id = $2, name = $3, rule = $4, target_cents = $5,
    drop_percent = $6, reference_cents = $7,
    reference_at = CASE WHEN $8::boolean THEN now() ELSE reference_at END,
    below = $9, interval_minutes = $10, updated_at = now()
WHERE id = $11
`

type UpdateWatchParams struct {
	ChannelID       int64
	TargetID        int64
	Name            string
	Rule            string
	TargetCents     *int64
	DropPercent     *float64
	ReferenceCents  int64
	ResetReference  bool
	Below           bool
	IntervalMinutes int32
	ID              int64
}

func (q *Queries) UpdateWatch(ctx context.Context, arg UpdateWatchParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateWatch,
		arg.ChannelID,
		arg.TargetID,
		arg.Name,
		arg.Rule,
		arg.TargetCents,
		arg.DropPercent,
		arg.ReferenceCents,
		arg.ResetReference,
		arg.Below,
		arg.IntervalMinutes,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
